formulas.latex:
\begin{aligned}
					&f:[a,b]\to \mathbb{R}\\
					&f \text{ is continuous in }a \Leftrightarrow \lim_{\substack{x\to a\\x<a}}f(x)=\lim_{\substack{x\to a\\x>a}}f(x)=f(a)\\
					&\left.\begin{matrix}
						f \text{ is continuous on } [a, b] \\
						f(a) \cdot f(b) < 0
					\end{matrix}
					\right\} \text{ there is at least a } c \in (a, b) \text{ such that } f(c) = 0
					\end{aligned}

